#!/bin/sh
# Writes AKitCore/Sources/AKitSkills/SkillModesExtensionSource.swift from
# Resources/akit-skill-modes.ts, the Pi extension `akit skills extension install` writes
# (skill-modes.md). In the code, not a bundle, like the flow templates (gen-flow-templates.sh).
# SkillModesExtensionTests keeps the generated file equal to the .ts (make test fails on drift).
set -eu
cd "$(dirname "$0")/.."
src=AKitCore/Sources/AKitSkills/Resources/akit-skill-modes.ts
out=AKitCore/Sources/AKitSkills/SkillModesExtensionSource.swift
tmp="$out.tmp"
if grep -q '"""####' "$src"; then echo "$src holds the raw-string end marker" >&2; exit 1; fi
{
  echo "// Generated by tools/gen-skill-modes-extension.sh from Resources/akit-skill-modes.ts. Do not edit by hand."
  echo "enum SkillModesExtensionSource {"
  printf '    static let akit_skill_modes_ts = ####"""\n'
  cat "$src"
  # Swift drops the newline right before the closing marker: add one so the text keeps its own.
  echo
  echo '"""####'
  echo "}"
} > "$tmp"
mv "$tmp" "$out"
